import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { parallaxScroll } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // ------------------------------------------------------------------------
  // Geometry & Material
  // ------------------------------------------------------------------------
  // Use aspect from the provided image (512x320) → 1.6:1
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const plane = new Mesh(geometry, material);
  plane.castShadow = true;
  root.add(plane);

  // ------------------------------------------------------------------------
  // Text content
  // ------------------------------------------------------------------------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.visualSpec?.colors?.paper ?? '#e8ecf2'),
      align: 'center',
    });
    // Slightly in front of the plane
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
  }

  // ------------------------------------------------------------------------
  // Interaction handlers (hover & click)
  // ------------------------------------------------------------------------
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(
    plane.position,
    {
      y: plane.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    },
  );

  const pressTL = gsap.timeline({ paused: true });
  pressTL.to(
    plane.scale,
    {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    },
  );

  root.userData.handlers = {
    hover: () => hoverTL.play(0),
    unhover: () => hoverTL.reverse(),
    click: () => {
      pressTL.restart();
      ctx.emit('hub-journal.select', {});
    },
  };

  // ------------------------------------------------------------------------
  // Cinematic primitives
  // ------------------------------------------------------------------------
  const primitiveInstances = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name && ctx.primitives[prim.name]) {
        const inst = ctx.primitives[prim.name](root, prim.params ?? {});
        primitiveInstances.push(inst);
      }
    }
  }

  // ------------------------------------------------------------------------
  // Cleanup
  // ------------------------------------------------------------------------
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    hoverTL.kill();
    pressTL.kill();
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
  };

  return root;
}
